// Explicit isolated fixtures only. These are never uploaded or used as actual
// pixel/semantic evidence. The content-motion tests exercise the raw inspector.
import {CONTENT_MOTION_POLICY as policy,MOTION_REPORT_SCHEMA,motionSha as sha,motionShotIssues,observationIntervals} from '../../lib/content-motion-contract.mts';
export function syntheticMotionReport(b,feedback=''){
 const frames=Math.round((b.video.duration||30)*30)-(b.qa?.outro_frames||119),shots=[{index:0,task_index:0,start_frame:0,end_frame:frames,kind:'video',source_sha256:sha('SYNTHETIC source'),source_start_frame:0,source_available_frames:frames,rate:1,role:'core',relevance:'direct',visible_content:'SYNTHETIC moving test subject',supports_narration:'SYNTHETIC script',measured_motion:true,observation:{classification:'moving-content',what_changed:'SYNTHETIC test subject movement',meaningful_change:true,text_only:false,relevance:'direct',duplicate_of:null,frame_sha256:[sha('SYNTHETIC frame1'),sha('SYNTHETIC frame2')]}}];
 return {schema:MOTION_REPORT_SCHEMA,policy_id:policy.id,policy_sha256:sha(policy),video_sha256:b.video.sha256,project_sha256:b.project.file_sha256,script_text_sha256:b.voice.script_text_sha256,feedback_sha256:sha(feedback),main_picture_only:true,frame_review_scope:'actual-export-main-picture-temporal-pairs',body_frames:frames,shots:observationIntervals(shots),metrics:{...motionShotIssues(observationIntervals(shots),frames,{observed:true,checkRepeats:false}).metrics,shot_count:shots.length},recipe_sha256:sha(shots),source_shots:shots,inspection_manifest_sha256:sha('SYNTHETIC manifest'),actual_frame_review_sha256:sha('SYNTHETIC review'),revision_checks:feedback?[{requirement:feedback,change:'SYNTHETIC changed visual',passed:true}]:[],human_quality_approved:false,publication_authorized:false};
}
export function motionFixtureApi(raw,feedback=()=> ''){return {...raw,beginLocalReviewDraft:async(id,b,actor)=>{b.qa.content_motion=syntheticMotionReport(b,await feedback(id));return raw.beginLocalReviewDraft(id,b,actor)}};}
export const syntheticInspector=async()=>({schema:'SYNTHETIC-independent-inspector-stub'});
